this->xmlWriter->startElement('sitemapindex'); $this->xmlWriter->writeAttribute('xmlns', 'http://www.sitemaps.org/schemas/sitemap/0.9'); $this->xmlWriter->writeAttribute('xmlns:xsi', 'http://www.w3.org/2001/XMLSchema-instance'); $this->xmlWriter->writeAttribute('xsi:schemaLocation', 'http://www.sitemaps.org/schemas/sitemap/0.9 http://www.sitemaps.org/schemas/sitemap/0.9/sitemap.xsd'); } private function writeSitemapIndexUrl($url) { $this->xmlWriter->startElement('sitemap'); $this->xmlWriter->writeElement('loc', htmlspecialchars($url, ENT_QUOTES)); $this->xmlWriter->writeElement('lastmod', date('c')); $this->xmlWriter->endElement(); } private function writeSitemapIndexEnd() { $this->xmlWriter->endElement(); $this->xmlWriter->endDocument(); } public function getGeneratedFiles(): array { return $this->generatedFiles; } public function submitSitemap(?string $yahooAppId = null): array { if (count($this->generatedFiles) === 0) { throw new BadMethodCallException("To update robots.txt, call finalize() first."); } if (!$this->runtime->extension_loaded('curl')) { throw new BadMethodCallException("cURL extension is needed to do submission."); } $searchEngines = $this->searchEngines; $searchEngines[0] = isset($yahooAppId) ? str_replace("USERID", $yahooAppId, $searchEngines[0][0]) : $searchEngines[0][1]; $result = []; for ($i = 0; $i < count($searchEngines); $i++) { $submitUrl = $searchEngines[$i] . htmlspecialchars($this->generatedFiles['sitemaps_index_url'], ENT_QUOTES); $submitSite = $this->runtime->curl_init($submitUrl); $this->runtime->curl_setopt($submitSite, CURLOPT_RETURNTRANSFER, true); $responseContent = $this->runtime->curl_exec($submitSite); $response = $this->runtime->curl_getinfo($submitSite); $submitSiteShort = array_reverse(explode(".", parse_url($searchEngines[$i], PHP_URL_HOST))); $result[] = [ "site" => $submitSiteShort[1] . "." . $submitSiteShort[0], "fullsite" => $submitUrl, "http_code" => $response['http_code'], "message" => str_replace("\n", " ", strip_tag